/**
 * Review report for a visual-baseline refresh (COR-1512; new code, not a port).
 *
 * Compares each regenerated baseline with the committed one it replaces:
 * - a changed pixel is one pixelmatch flags at the suite's `threshold: 0.1`,
 *   and the ratio is changed pixels over the new image's width times height;
 * - unchanged means pixel-identical (byte-identical is a subset);
 * - a dimension change is reported as such, with no ratio;
 * - added baselines (no committed counterpart) and orphaned ones (committed
 *   but not regenerated by any test) are listed separately. Orphans stay in
 *   place; deleting them is out of scope.
 *
 * Writes `baseline-diff-report.json`, `baseline-diff-report.md`, and a diff
 * image per changed baseline. `filesToApply` names exactly the files a refresh
 * commits, so unchanged rewrites keep their original bytes.
 */
import { existsSync, readFileSync } from 'node:fs';
import { mkdir, readdir } from 'node:fs/promises';
import { dirname, join, relative } from 'node:path';

import pixelmatch from 'pixelmatch';
import { PNG } from 'pngjs';

/** The suite's `toHaveScreenshot` threshold (`SNAPSHOT_DIFF_OPTIONS` in @lostgradient/testing). */
export const PIXEL_THRESHOLD = 0.1;
/** Changed baselines above this ratio need a review classification. */
export const CLASSIFICATION_RATIO = 0.01;

export type BaselineComparison =
  | { path: string; kind: 'unchanged'; byteIdentical: boolean }
  | {
      path: string;
      kind: 'changed';
      changedPixels: number;
      totalPixels: number;
      ratio: number;
    }
  | {
      path: string;
      kind: 'dimensions';
      oldSize: { width: number; height: number };
      newSize: { width: number; height: number };
    }
  | { path: string; kind: 'added' };

export type BaselineDiffReport = {
  comparisons: BaselineComparison[];
  orphaned: string[];
  counts: {
    regenerated: number;
    changed: number;
    dimensionChanged: number;
    unchanged: number;
    byteIdentical: number;
    added: number;
    orphaned: number;
    needsClassification: number;
  };
};

export type PairComparison = {
  comparison: BaselineComparison;
  diffImage?: Buffer;
};

/** Compare one committed baseline with its regenerated replacement. */
export function compareBaselinePair(
  path: string,
  oldBytes: Buffer | undefined,
  newBytes: Buffer,
): PairComparison {
  if (oldBytes === undefined) return { comparison: { path, kind: 'added' } };
  if (oldBytes.equals(newBytes)) {
    return { comparison: { path, kind: 'unchanged', byteIdentical: true } };
  }
  const before = PNG.sync.read(oldBytes);
  const after = PNG.sync.read(newBytes);
  if (before.width !== after.width || before.height !== after.height) {
    return {
      comparison: {
        path,
        kind: 'dimensions',
        oldSize: { width: before.width, height: before.height },
        newSize: { width: after.width, height: after.height },
      },
    };
  }
  const diff = new PNG({ width: after.width, height: after.height });
  const changedPixels = pixelmatch(before.data, after.data, diff.data, after.width, after.height, {
    threshold: PIXEL_THRESHOLD,
  });
  if (changedPixels === 0) {
    return { comparison: { path, kind: 'unchanged', byteIdentical: false } };
  }
  const totalPixels = after.width * after.height;
  return {
    comparison: {
      path,
      kind: 'changed',
      changedPixels,
      totalPixels,
      ratio: changedPixels / totalPixels,
    },
    diffImage: PNG.sync.write(diff),
  };
}

/** Every `.png` under `directory`, as forward-slash paths relative to it, sorted. */
export async function listBaselines(directory: string): Promise<string[]> {
  if (!existsSync(directory)) return [];
  const entries = await readdir(directory, { recursive: true, withFileTypes: true });
  return entries
    .filter((entry) => entry.isFile() && entry.name.endsWith('.png'))
    .map((entry) => relative(directory, join(entry.parentPath, entry.name)).split('\\').join('/'))
    .toSorted();
}

/**
 * Normalize the container's `find` output (repository-relative paths) to paths
 * relative to the Linux baseline directory.
 */
export function parseRegeneratedList(text: string, baselineDirectory: string): string[] {
  const prefix = `${baselineDirectory.replace(/\/$/, '')}/`;
  return [
    ...new Set(
      text
        .split('\n')
        .map((line) => line.trim().replace(/^\.\//, ''))
        .filter((line) => line.endsWith('.png'))
        .map((line) => (line.startsWith(prefix) ? line.slice(prefix.length) : line)),
    ),
  ].toSorted();
}

export type BuildReportOptions = {
  oldDirectory: string;
  newDirectory: string;
  regenerated: readonly string[];
  diffDirectory?: string;
};

export async function buildBaselineDiffReport(
  options: BuildReportOptions,
): Promise<BaselineDiffReport> {
  const regenerated = new Set(options.regenerated);
  const comparisons: BaselineComparison[] = [];
  for (const path of [...regenerated].toSorted()) {
    const oldPath = join(options.oldDirectory, path);
    const oldBytes = existsSync(oldPath) ? readFileSync(oldPath) : undefined;
    const { comparison, diffImage } = compareBaselinePair(
      path,
      oldBytes,
      readFileSync(join(options.newDirectory, path)),
    );
    comparisons.push(comparison);
    if (diffImage !== undefined && options.diffDirectory !== undefined) {
      const target = join(options.diffDirectory, path.replace(/\.png$/, '-diff.png'));
      await mkdir(dirname(target), { recursive: true });
      await Bun.write(target, diffImage);
    }
  }
  const committed = await listBaselines(options.oldDirectory);
  const orphaned = committed.filter((path) => !regenerated.has(path));
  const of = (kind: BaselineComparison['kind']) =>
    comparisons.filter((comparison) => comparison.kind === kind);
  const unchanged = of('unchanged');
  return {
    comparisons,
    orphaned,
    counts: {
      regenerated: comparisons.length,
      changed: of('changed').length,
      dimensionChanged: of('dimensions').length,
      unchanged: unchanged.length,
      byteIdentical: unchanged.filter(
        (comparison) => 'byteIdentical' in comparison && comparison.byteIdentical,
      ).length,
      added: of('added').length,
      orphaned: orphaned.length,
      needsClassification: needsClassification(comparisons).length,
    },
  };
}

/** Changed baselines above the classification ratio, plus every dimension change. */
export function needsClassification(
  comparisons: readonly BaselineComparison[],
): BaselineComparison[] {
  return comparisons.filter(
    (comparison) =>
      comparison.kind === 'dimensions' ||
      (comparison.kind === 'changed' && comparison.ratio > CLASSIFICATION_RATIO),
  );
}

/** The baselines a refresh commits: pixel-changed, dimension-changed, and added. */
export function filesToApply(report: BaselineDiffReport): string[] {
  return report.comparisons
    .filter((comparison) => comparison.kind !== 'unchanged')
    .map((comparison) => comparison.path);
}

function percent(ratio: number): string {
  return `${(ratio * 100).toFixed(3)}%`;
}

export function renderReportMarkdown(report: BaselineDiffReport, heading: string): string {
  const { counts } = report;
  const lines = [
    `# ${heading}`,
    '',
    `Pixel comparison: pixelmatch at threshold ${PIXEL_THRESHOLD}. The ratio is changed pixels over the new image's width times height. Images above ${percent(CLASSIFICATION_RATIO)} need a classification: (a) rasterizer or toolchain drift, (b) an intentional source change never re-baselined (cite the commit), or (c) an unintended regression.`,
    '',
    '| Category | Count |',
    '| --- | --- |',
    `| Regenerated | ${counts.regenerated} |`,
    `| Changed (pixels) | ${counts.changed} |`,
    `| Dimension changed | ${counts.dimensionChanged} |`,
    `| Unchanged (pixel-identical) | ${counts.unchanged} |`,
    `| Unchanged and byte-identical | ${counts.byteIdentical} |`,
    `| Added | ${counts.added} |`,
    `| Orphaned (not regenerated, left in place) | ${counts.orphaned} |`,
    `| Needs classification (above ${percent(CLASSIFICATION_RATIO)}) | ${counts.needsClassification} |`,
    '',
    '## Changed baselines',
    '',
  ];
  const changed = report.comparisons
    .filter((comparison) => comparison.kind === 'changed')
    .toSorted((left, right) => right.ratio - left.ratio);
  if (changed.length === 0) lines.push('None.');
  else {
    lines.push(
      '| Baseline | Changed pixels | Ratio | Classification |',
      '| --- | --- | --- | --- |',
    );
    for (const comparison of changed) {
      const classification =
        comparison.ratio > CLASSIFICATION_RATIO ? 'to classify' : 'below threshold';
      lines.push(
        `| \`${comparison.path}\` | ${comparison.changedPixels} | ${percent(comparison.ratio)} | ${classification} |`,
      );
    }
  }
  const section = (title: string, items: readonly string[]) => {
    lines.push('', `## ${title}`, '');
    if (items.length === 0) lines.push('None.');
    else lines.push(...items);
  };
  const code = (path: string) => `- \`${path}\``;
  section(
    'Dimension changes',
    report.comparisons.flatMap((comparison) =>
      comparison.kind === 'dimensions'
        ? [
            `${code(comparison.path)}: ${comparison.oldSize.width}x${comparison.oldSize.height} to ${comparison.newSize.width}x${comparison.newSize.height}`,
          ]
        : [],
    ),
  );
  section(
    'Added baselines',
    report.comparisons.filter((comparison) => comparison.kind === 'added').map((c) => code(c.path)),
  );
  section('Orphaned baselines', report.orphaned.map(code));
  return `${lines.join('\n')}\n`;
}

export async function writeBaselineDiffReport(
  report: BaselineDiffReport,
  outputDirectory: string,
  heading: string,
): Promise<{ json: string; markdown: string }> {
  await mkdir(outputDirectory, { recursive: true });
  const json = join(outputDirectory, 'baseline-diff-report.json');
  const markdown = join(outputDirectory, 'baseline-diff-report.md');
  await Bun.write(json, `${JSON.stringify(report, null, 2)}\n`);
  await Bun.write(markdown, renderReportMarkdown(report, heading));
  return { json, markdown };
}
